fn swap3(a: &mut Vec<i32>, h: usize, i: usize, j: usize) {
    // Temporarily save the value at h
    let temp = a[h];
    // Move the value from i to h
    a[h] = a[i];
    // Move the value from j to i
    a[i] = a[j];
    // Finally, move the original h‐value into j
    a[j] = temp;
}

